// scripts/test-t1-9bw.js
// T1.9BW: Android ready for testing. The Android project is generated by EAS from app.json (like
// iOS), Firebase's google-services.json comes from an EAS file variable, and an APK profile exists.
//   node .\scripts\test-t1-9bw.js
"use strict";
const fs = require("fs");
const path = require("path");
const assert = require("assert");

const root = path.resolve(__dirname, "..");
const read = (f) => fs.readFileSync(path.join(root, f), "utf8");
let n = 0;
const ok = (cond, msg) => { assert(cond, msg); n++; };

const app = JSON.parse(read("app.json")).expo;
ok(app.android.package === "com.kjfok.lostorfound", "package name");
const notif = app.plugins.find((p) => Array.isArray(p) && p[0] === "expo-notifications");
ok(notif && notif[1].icon === "./assets/images/android-icon-monochrome.png", "white notification icon for Android");
ok(fs.existsSync(path.join(root, "assets/images/android-icon-monochrome.png")), "icon file exists");

// app.config.js adds google-services.json only when it is available.
const makeConfig = require(path.join(root, "app.config.js"));
const base = { name: "x", android: { package: "com.kjfok.lostorfound" } };
const saved = process.env.GOOGLE_SERVICES_JSON;
process.env.GOOGLE_SERVICES_JSON = "/tmp/eas/google-services.json";
ok(makeConfig({ config: base }).android.googleServicesFile === "/tmp/eas/google-services.json", "EAS file variable is used");
delete process.env.GOOGLE_SERVICES_JSON;
const local = fs.existsSync(path.join(root, "google-services.json"));
ok(local ? makeConfig({ config: base }).android.googleServicesFile === "./google-services.json" : !("googleServicesFile" in makeConfig({ config: base }).android), "no file, no setting");
ok(makeConfig({ config: base }).android.package === "com.kjfok.lostorfound", "the rest of app.json is kept");
if (saved !== undefined) process.env.GOOGLE_SERVICES_JSON = saved;

// Secrets and generated folders stay out of git.
const ignore = read(".gitignore");
for (const line of ["android/", "ios/", "google-services.json", "*firebase-adminsdk*.json"]) ok(ignore.split(/\r?\n/).includes(line), `.gitignore has ${line}`);

// An installable test build.
const eas = JSON.parse(read("eas.json"));
ok(eas.build["android-apk"] && eas.build["android-apk"].extends === "production" && eas.build["android-apk"].android.buildType === "apk", "android-apk profile");

console.log(`OK: T1.9BW ${n} checks`);
